pixel_box.grammar:
bbox ::= bbox-0 | null
bbox-0 ::= "[" space number ("," space number){3,3} space "]"
bbox-kv ::= "\"bbox\"" space ":" space bbox
decimal-part ::= [0-9]{1,16}
integral-part ::= [0] | [1-9] [0-9]{0,15}
null ::= "null"
number ::= ("-"? integral-part) ("." decimal-part)? ([eE] [-+]? integral-part)?
root ::= "{" space bbox-kv space "}"
space ::= | " " | "\n"{1,2} [ \t]{0,20}
